public void render(PoseStack poseStack, int packedLightIn, MultiBufferSource bufferIn, ItemStack stack) {
        poseStack.pushPose();
        translateAndRotate(poseStack);

        //Y - Front/Back
        //X - Left/Right
        //Z - Up/Down
        poseStack.mulPose(Axis.ZP.rotationDegrees(180.0F));
        poseStack.translate(0, -0.145, 0.35);
        poseStack.scale(1.03F, 1.03F, 1.03F);

        ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
        itemRenderer.renderStatic(stack, ItemDisplayContext.NONE, packedLightIn, OverlayTexture.NO_OVERLAY, poseStack, bufferIn, Minecraft.getInstance().level, 0);

        //Render Tools
        this.tools.render(stack, bufferIn, poseStack, packedLightIn, OverlayTexture.NO_OVERLAY);

        poseStack.popPose();
    }

public void copyFrom(ModelPart parentModelPart) {
        this.xScale = parentModelPart.xScale;
        this.yScale = parentModelPart.yScale;
        this.zScale = parentModelPart.zScale;
        this.xRot = parentModelPart.xRot;
        this.yRot = parentModelPart.yRot;
        this.zRot = parentModelPart.zRot;
        this.x = parentModelPart.x;
        this.y = parentModelPart.y;
        this.z = parentModelPart.z;
    }

protected void translateAndRotate(PoseStack poseStack) {
        poseStack.translate(this.x / 16.0f, this.y / 16.0f, this.z / 16.0f);
        if(this.xRot != 0.0f || this.yRot != 0.0f || this.zRot != 0.0f) {
            poseStack.mulPose(new Quaternionf().rotationZYX(this.zRot, this.yRot, this.xRot));
        }
        if(this.xScale != 1.0f || this.yScale != 1.0f || this.zScale != 1.0f) {
            poseStack.scale(this.xScale, this.yScale, this.zScale);
        }
    }

public List<ItemStack> prepare(ItemStack stack) {
        if(NbtHelper.has(stack, ModDataHelper.TOOLS_CONTAINER)) {
            return new ArrayList<>(((NonNullList<ItemStack>)NbtHelper.get(stack, ModDataHelper.TOOLS_CONTAINER)).stream().filter(itemStack -> !itemStack.isEmpty()).toList());
        } else {
            return new ArrayList<>();
        }
    }

public void render(ItemStack backpack, MultiBufferSource buffer, PoseStack poseStack, int light, int overlay) {
        if(buffer == null || !TravelersBackpackConfig.CLIENT.renderTools.get()) {
            return;
        }
        render(prepare(backpack), poseStack, buffer, light, overlay);
    }

public void render(List<ItemStack> tools, PoseStack poseStack, MultiBufferSource buffer, int pPackedLight, int pPackedOverlay) {
        if(tools.isEmpty()) return;

        ItemStack toolUpper = tools.get(0);
        ItemStack toolLower = ItemStack.EMPTY;

        if(!toolUpper.isEmpty() && tools.size() > 1) {
            toolLower = tools.get(tools.size() - 1);
        }

        poseStack.pushPose();

        if(!toolUpper.isEmpty()) {
            BakedModel model = Minecraft.getInstance().getItemRenderer().getModel(toolUpper, null, null, 0);
            model = applyTransform(model, poseStack);

            poseStack.pushPose();
            RenderSystem.enableBlend();
            RenderSystem.blendFuncSeparate(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA, 1, 0);

            poseStack.mulPose(Axis.ZP.rotationDegrees(180.0F));

            poseStack.translate(0.04D, 0.075D, 0.17D);
            poseStack.mulPose(Axis.ZP.rotationDegrees(45F));
            poseStack.mulPose(Axis.XP.rotationDegrees(180F));
            poseStack.scale(0.50F, 0.50F, 0.50F);

            RenderSystem.setShader(GameRenderer::getPositionTexShader);
            RenderSystem.setShaderTexture(0, InventoryMenu.BLOCK_ATLAS);
            Minecraft.getInstance().getItemRenderer().render(toolUpper, getDisplayContext(toolUpper), false, poseStack, buffer, pPackedLight, pPackedOverlay, model);

            RenderSystem.disableBlend();
            poseStack.popPose();
        }

        if(!toolLower.isEmpty()) {
            BakedModel model = Minecraft.getInstance().getItemRenderer().getModel(toolLower, null, null, 0);
            model = applyTransform(model, poseStack);

            poseStack.pushPose();
            RenderSystem.enableBlend();
            RenderSystem.blendFuncSeparate(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA, 1, 0);

            poseStack.mulPose(Axis.ZP.rotationDegrees(180.0F));

            poseStack.translate(-0.25, 0.75, -0.025);
            poseStack.mulPose(Axis.YP.rotationDegrees(90F));
            poseStack.mulPose(Axis.ZP.rotationDegrees(45F));
            poseStack.scale(0.50F, 0.50F, 0.50F);

            RenderSystem.setShader(GameRenderer::getPositionTexShader);
            RenderSystem.setShaderTexture(0, InventoryMenu.BLOCK_ATLAS);
            Minecraft.getInstance().getItemRenderer().render(toolLower, getDisplayContext(toolLower), false, poseStack, buffer, pPackedLight, pPackedOverlay, model);

            RenderSystem.disableBlend();
            poseStack.popPose();
        }

        poseStack.popPose();
    }

public BakedModel applyTransform(BakedModel model, PoseStack poseStack) {
        return model.applyTransform(ItemDisplayContext.NONE, poseStack, false);
    }

public ItemDisplayContext getDisplayContext(ItemStack stack) {
        if(stack.is(Items.TRIDENT) || stack.is(Items.SPYGLASS)) {
            return ItemDisplayContext.GUI;
        }
        return ItemDisplayContext.NONE;
    }

public void render(PoseStack poseStack, int packedLightIn) {
        poseStack.pushPose();
        translateAndRotate(poseStack);
        BakedModel starModel = Minecraft.getInstance().getModelManager().getModel(ModClientEventHandler.STAR_MODEL);

        //Y - Front/Back
        //X - Left/Right
        //Z - Up/Down
        poseStack.translate(0.05, 0.23, 0.405);
        poseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
        poseStack.scale(0.3F, 0.3F, 0.3F);
        poseStack.mulPose(Axis.YP.rotationDegrees(-10.0F));

        renderModel(poseStack, starModel, packedLightIn);
        poseStack.popPose();
    }

private void renderModel(PoseStack matrixStack, BakedModel model, int packedLightIn) {
        MultiBufferSource.BufferSource src = Minecraft.getInstance().renderBuffers().bufferSource();
        VertexConsumer worldrenderer = src.getBuffer(RenderType.entityCutout(TextureAtlas.LOCATION_BLOCKS));
        List<BakedQuad> quads = model.getQuads(null, null, RANDOM, ModelData.EMPTY, null);
        for(BakedQuad quad : quads) {
            worldrenderer.putBulkData(matrixStack.last(), quad, 1.0f, 1.0f, 1.0f, 1.0f, packedLightIn, OverlayTexture.NO_OVERLAY, true);
        }
        src.endBatch();
    }

