public AccessCommand(CommandDispatcher<CommandSourceStack> dispatcher) {
        LiteralArgumentBuilder<CommandSourceStack> tbCommand = Commands.literal("tb").requires(player -> player.hasPermission(2));

        tbCommand.then(Commands.literal("access")
                .then(Commands.argument("pos", BlockPosArgument.blockPos())
                        .executes(source -> openTargetBlockEntity(source.getSource(), BlockPosArgument.getLoadedBlockPos(source, "pos"))))
                .then(Commands.argument("target", EntityArgument.players())
                        .executes(source -> openTargetInventory(source.getSource(), EntityArgument.getPlayer(source, "target")))));

        dispatcher.register(tbCommand);
    }

public int openTargetBlockEntity(CommandSourceStack source, BlockPos blockPos) throws CommandSyntaxException {
        if(source.getLevel().getBlockEntity(blockPos) instanceof BackpackBlockEntity backpackBlockEntity) {
            backpackBlockEntity.openBackpackFromCommand(source.getPlayerOrException(), backpackBlockEntity, blockPos);
            source.sendSuccess(() -> Component.literal("Accessing backpack of " + blockPos.toShortString()), true);
            return 1;
        } else {
            source.sendFailure(Component.literal("There's no backpack at coordinates " + blockPos.toShortString()));
            return -1;
        }
    }

public int openTargetInventory(CommandSourceStack source, ServerPlayer target) throws CommandSyntaxException {
        ServerPlayer self = source.getPlayerOrException();
        boolean hasBackpack = CapabilityUtils.isWearingBackpack(target);
        ItemStack stack = CapabilityUtils.getWearingBackpack(target);

        if(hasBackpack) {
            BackpackContainer.openAnotherPlayerBackpack(self, target, stack, Reference.WEARABLE_SCREEN_ID);
            source.sendSuccess(() -> Component.literal("Accessing backpack of " + target.getDisplayName().getString()), true);
            return 1;
        } else {
            source.sendFailure(Component.literal("Can't access backpack"));
            return -1;
        }
    }

public BackpackIconCommands(CommandDispatcher<CommandSourceStack> dispatcher) {
        dispatcher.register(Commands.literal("tb_client")
                .then(Commands.literal("hide").executes(source -> hideIcon(source.getSource())))
                .then(Commands.literal("show").executes(source -> showIcon())));
    }

public int hideIcon(CommandSourceStack source) {
        TravelersBackpackConfig.CLIENT.showBackpackIconInInventory.set(false);
        TravelersBackpackConfig.CLIENT.showBackpackIconInInventory.save();
        source.sendSuccess(() -> Component.translatable("screen.travelersbackpack.hidden_icon_info"), true);
        return 1;
    }

public int showIcon() {
        TravelersBackpackConfig.CLIENT.showBackpackIconInInventory.set(true);
        TravelersBackpackConfig.CLIENT.showBackpackIconInInventory.save();
        return 1;
    }

public ClearCommand(CommandDispatcher<CommandSourceStack> dispatcher) {
        LiteralArgumentBuilder<CommandSourceStack> tbCommand = Commands.literal("tb").requires(player -> player.hasPermission(2));

        tbCommand.then(Commands.literal("remove")
                .executes(source -> removeBackpack(source.getSource(), source.getSource().getPlayerOrException()))
                .then(Commands.argument("player", EntityArgument.player())
                        .executes(source -> removeBackpack(source.getSource(), EntityArgument.getPlayer(source, "player")))));

        tbCommand.then(Commands.literal("clear")
                .executes(source -> clearBackpack(source.getSource(), source.getSource().getPlayerOrException()))
                .then(Commands.argument("player", EntityArgument.player())
                        .executes(source -> clearBackpack(source.getSource(), EntityArgument.getPlayer(source, "player")))));

        dispatcher.register(tbCommand);
    }

private static int removeBackpack(CommandSourceStack source, ServerPlayer player) {
        if(CapabilityUtils.isWearingBackpack(player)) {
            if(TravelersBackpack.enableIntegration()) return -1;

            CapabilityUtils.getCapability(player).ifPresent(data -> {
                if(!player.addItem(data.getBackpack().copy())) {
                    player.drop(data.getBackpack().copy(), true);
                }
                data.equipBackpack(ItemStack.EMPTY);
                data.synchronise();
            });
            source.sendSuccess(() -> Component.literal("Removed Traveler's Backpack from " + player.getDisplayName().getString() + " and added copy to inventory"), true);
            return 1;
        } else {
            source.sendFailure(Component.literal("Player " + player.getDisplayName().getString() + " is not wearing backpack"));
            return -1;
        }
    }

private static int clearBackpack(CommandSourceStack source, ServerPlayer player) {
        if(CapabilityUtils.isWearingBackpack(player)) {
            if(TravelersBackpack.enableIntegration()) return -1;

            CapabilityUtils.getCapability(player).ifPresent(data -> {
                ItemStack stack = data.getBackpack().copy();
                if(!player.addItem(stack.copy())) {
                    player.drop(stack.copy(), true);
                }
                int tier = NbtHelper.getOrDefault(stack, ModDataHelper.TIER, 0);
                ItemStack clearedStack = stack.getItem().getDefaultInstance();
                NbtHelper.set(clearedStack, ModDataHelper.TIER, tier);
                data.equipBackpack(clearedStack);
                data.synchronise();
            });
            source.sendSuccess(() -> Component.literal("Cleared contents of Traveler's Backpack from " + player.getDisplayName().getString() + " and added copy to inventory"), true);
            return 1;
        } else {
            source.sendFailure(Component.literal("Player " + player.getDisplayName().getString() + " is not wearing backpack"));
            return -1;
        }
    }

public RestoreCommand(CommandDispatcher<CommandSourceStack> dispatcher) {
        LiteralArgumentBuilder<CommandSourceStack> tbCommand = Commands.literal("tb").requires(player -> player.hasPermission(2));

        tbCommand.then(Commands.literal("restore")
                .then(Commands.argument("target", EntityArgument.player())
                        .then(Commands.argument("backpack_id", StringArgumentType.string()).suggests(SUGGESTION_PROVIDER)
                                .executes(source -> restoreBackpack(source.getSource(), StringArgumentType.getString(source, "backpack_id"), EntityArgument.getPlayer(source, "target"))))));

        dispatcher.register(tbCommand);
    }

public int restoreBackpack(CommandSourceStack source, String backpackID, ServerPlayer player) {
        ItemStack backpack = BackpackManager.getBackpack(player.serverLevel(), backpackID);
        if(backpack == null) {
            source.sendFailure(Component.literal("Backpack with ID " + backpackID + " not found"));
            return 0;
        }
        if(!player.getInventory().add(backpack)) {
            player.drop(backpack, false);
        }
        source.sendSuccess(() -> Component.literal("Successfully restored " + player.getDisplayName().getString() + "'s backpack"), true);
        return 1;
    }

public UnpackCommand(CommandDispatcher<CommandSourceStack> dispatcher) {
        LiteralArgumentBuilder<CommandSourceStack> tbCommand = Commands.literal("tb").requires(player -> player.hasPermission(2));

        tbCommand.then(Commands.literal("unpack")
                .then(Commands.argument("pos", BlockPosArgument.blockPos())
                        .executes(source -> unpackTargetBlockEntity(source.getSource(), BlockPosArgument.getLoadedBlockPos(source, "pos"))))
                .then(Commands.argument("target", EntityArgument.players())
                        .executes(source -> unpackTargetInventory(source.getSource(), EntityArgument.getPlayer(source, "target")))));

        dispatcher.register(tbCommand);
    }

public int unpackTargetBlockEntity(CommandSourceStack source, BlockPos blockPos) {
        if(source.getLevel().getBlockEntity(blockPos) instanceof BackpackBlockEntity blockEntity) {
            NonNullList<ItemStack> stacks = collectItems(blockEntity.getWrapper());
            if(!stacks.isEmpty()) {
                if(!source.getLevel().isClientSide) {
                    Containers.dropContents(source.getLevel(), blockPos, stacks);
                }
                source.sendSuccess(() -> Component.literal("Dropping contents of backpack placed at " + blockPos.toShortString()), true);
                return 1;
            } else {
                source.sendFailure(Component.literal("There's no contents in backpack at coordinates " + blockPos.toShortString()));
                return -1;
            }
        } else {
            source.sendFailure(Component.literal("There's no backpack at coordinates " + blockPos.toShortString()));
            return -1;
        }
    }

public int unpackTargetInventory(CommandSourceStack source, ServerPlayer serverPlayer) {
        boolean hasBackpack = CapabilityUtils.isWearingBackpack(serverPlayer);
        if(TravelersBackpack.enableIntegration()) return -1;

        if(hasBackpack) {
            AtomicBoolean flag = new AtomicBoolean(false);
            CapabilityUtils.getCapability(serverPlayer).ifPresent(data -> {
                NonNullList<ItemStack> stacks = collectItems(data.getWrapper());
                if(!stacks.isEmpty()) {
                    if(!source.getLevel().isClientSide) {
                        data.synchronise();
                        Containers.dropContents(source.getLevel(), serverPlayer.blockPosition(), stacks);
                        flag.set(true);
                    }
                }
            });
            if(flag.get()) {
                source.sendSuccess(() -> Component.literal("Dropping contents of " + serverPlayer.getDisplayName().getString() + " backpack at " + serverPlayer.blockPosition().toShortString()), true);
                return 1;
            } else {
                source.sendFailure(Component.literal("There's no contents in " + serverPlayer.getDisplayName().getString() + " backpack"));
                return -1;
            }
        } else {
            source.sendFailure(Component.literal("Player " + serverPlayer.getDisplayName().getString() + " is not wearing backpack"));
            return -1;
        }
    }

public NonNullList<ItemStack> collectItems(BackpackWrapper wrapper) {
        NonNullList<ItemStack> stacks = NonNullList.create();
        stacks.addAll(collectItems(wrapper.getStorage()));
        stacks.addAll(collectItems(wrapper.getTools()));
        stacks.addAll(collectItems(wrapper.getUpgrades()));
        return stacks;
    }

public NonNullList<ItemStack> collectItems(ItemStackHandler handler) {
        NonNullList<ItemStack> stacks = NonNullList.create();
        for(int i = 0; i < handler.getSlots(); i++) {
            ItemStack stackInSlot = handler.getStackInSlot(i);
            if(!stackInSlot.isEmpty()) {
                stacks.add(stackInSlot);
                handler.setStackInSlot(i, ItemStack.EMPTY);
            }
        }
        return stacks;
    }

public boolean abilityTick(@Nullable ItemStack backpack, @Nullable Player player) {
        boolean tickCooldown = false;
        if(backpack != null) {
            Item backpackItem = backpack.getItem();

            //Check if backpack has cooldown set in config
            boolean effectHasCooldown = false;

            //Has effect associated
            if(getBackpackEffects().containsKey(backpack.getItem())) {
                //Check if there's backpack entry in cooldowns config
                if(getCooldowns().containsKey(backpack.getItem())) {
                    effectHasCooldown = true;
                }
                //If not, then add timed mob effect and re-apply them, without any cooldown ticking
                if(!effectHasCooldown) {
                    Collection<BackpackEffect> backpackEffects = getBackpackEffects().get(backpackItem);
                    for(BackpackEffect backpackEffect : backpackEffects) {

                        //Squid Backpack Exception - Night Vision only works underwater
                        if(backpack.getItem() == ModItems.SQUID_TRAVELERS_BACKPACK.get() && backpackEffect.effect() == MobEffects.NIGHT_VISION) {
                            if(!player.isInWater()) {
                                continue;
                            }
                        }

                        addTimedMobEffect(player, backpackEffect.effect(), backpackEffect.minDuration(), backpackEffect.maxDuration(), backpackEffect.amplifier(), false, false, false);
                    }
                } else { //If yes, then check if there's active cooldown
                    //If no active cooldown
                    if(!hasCooldown(backpack)) {
                        //Apply effects
                        Collection<BackpackEffect> backpackEffects = getBackpackEffects().get(backpackItem);
                        for(BackpackEffect backpackEffect : backpackEffects) {

                            //Custom handling for squid's water breathing
                            //if(backpackEffect.effect() == MobEffects.WATER_BREATHING && backpackItem == ModItems.SQUID_TRAVELERS_BACKPACK.get()) {
                            //    squidAbility(backpack, player, backpackEffect.minDuration(), backpackEffect.maxDuration(), backpackEffect.amplifier());
                            //}

                            //Custom handling for magma cube's fire resistance
                            //if(backpackEffect.effect() == MobEffects.FIRE_RESISTANCE && backpackItem == ModItems.MAGMA_CUBE_TRAVELERS_BACKPACK.get()) {
                            //    magmaCubeAbility(backpack, player, backpackEffect.minDuration(), backpackEffect.maxDuration(), backpackEffect.amplifier());
                            //}

                            addTimedMobEffect(player, backpackEffect.effect(), backpackEffect.minDuration(), backpackEffect.maxDuration(), backpackEffect.amplifier(), false, false, false);
                        }
                        //Apply cooldown
                        setCooldown(CapabilityUtils.getBackpackWrapperArtificial(player), backpackItem);
                    }
                    //Tick cooldown, but return at the end to check if there's any custom ability associated with backpack
                    tickCooldown = true;
                }
            }

            if(backpackItem == ModItems.NETHERITE_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.ARMOR, NETHERITE_ARMOR_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.DIAMOND_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.ARMOR, DIAMOND_ARMOR_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.GOLD_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.ARMOR, GOLD_ARMOR_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.EMERALD_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.LUCK, EMERALD_LUCK);
                return false;
            }

            if(backpackItem == ModItems.IRON_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.ARMOR, IRON_ARMOR_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.ENDERMAN_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, ForgeMod.BLOCK_REACH.get(), ENDERMAN_REACH_DISTANCE_MODIFIER);
                attributeAbility(player, false, ForgeMod.ENTITY_REACH.get(), ENDERMAN_REACH_DISTANCE_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.WARDEN_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.MAX_HEALTH, WARDEN_MAX_HEALTH_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.FOX_TRAVELERS_BACKPACK.get()) {
                attributeAbility(player, false, Attributes.MOVEMENT_SPEED, FOX_MOVEMENT_SPEED_MODIFIER);
                return false;
            }

            if(backpackItem == ModItems.CAKE_TRAVELERS_BACKPACK.get()) {
                cakeAbility(backpack, player);
                return true;
            }

            if(backpackItem == ModItems.CACTUS_TRAVELERS_BACKPACK.get()) {
                cactusAbilityEquipped(player, backpack);
                return false;
            }

            if(backpackItem == ModItems.CHICKEN_TRAVELERS_BACKPACK.get()) {
                chickenAbility(backpack, player, false);
                return true;
            }

            if(backpackItem == ModItems.CREEPER_TRAVELERS_BACKPACK.get()) {
                return true;
            }

            if(backpackItem == ModItems.BLAZE_TRAVELERS_BACKPACK.get()) {
                blazeAbility(player);
                return false;
            }

            if(backpackItem == ModItems.SPIDER_TRAVELERS_BACKPACK.get()) {
                spiderAbility(player);
                return false;
            }

            if(backpackItem == ModItems.OCELOT_TRAVELERS_BACKPACK.get()) {
                ocelotAbility(player);
                return false;
            }

            if(backpackItem == ModItems.COW_TRAVELERS_BACKPACK.get()) {
                cowAbility(backpack, player);
                return true;
            }

            if(backpackItem == ModItems.WITHER_TRAVELERS_BACKPACK.get()) {
                witherAbilityTick(player);
                return false;
            }
        }
        return tickCooldown;
    }

