public ShapedBackpackRecipeBuilder createFullGrid(Item result, Ingredient ingredient, Ingredient ingredient1, Item unlocker, TagKey<Item> tag) {
        return ShapedBackpackRecipeBuilder.shaped(RecipeCategory.MISC, result)
                .define('A', ingredient1).define('B', ingredient)
                .pattern("AAA").pattern("ABA").pattern("AAA").unlockedBy(getHasName(unlocker), has(tag));
    }

public BackpackItemEntity(EntityType<? extends ItemEntity> entityType, Level level) {
        super(entityType, level);
        boolean neverDespawn = TravelersBackpackConfig.SERVER.backpackSettings.neverDespawn.get();
        if(neverDespawn) {
            this.setUnlimitedLifetime();
        }
        this.fireResistant = TravelersBackpackConfig.SERVER.backpackSettings.fireResistant.get();
        this.explosionResistant = TravelersBackpackConfig.SERVER.backpackSettings.explosionResistant.get();
        this.invulnerableBackpack = TravelersBackpackConfig.SERVER.backpackSettings.invulnerableBackpack.get();
    }

@Override
    public void tick() {
        if(TravelersBackpackConfig.SERVER.backpackSettings.voidProtection.get()) {
            if(!this.level().isClientSide && !isNoGravity() && wasFloatingUp && getY() < level().getMinBuildHeight()) {
                if(random.nextFloat() > 0.25F) {
                    float ab = random.nextFloat() * 2.0f;
                    float ag = random.nextFloat() * ((float)Math.PI * 2);
                    double n = Mth.cos(ag) * ab;
                    double o = 0.01 + random.nextDouble() * 0.5;
                    double p = Mth.sin(ag) * ab;
                    ((ServerLevel)level()).sendParticles(ParticleTypes.DRAGON_BREATH, position().x() + n * 0.1, position().y() + 0.3, position().z() + p * 0.1, 0, n * 0.01F, o * 0.1F, p * 0.01F, 1.0F);
                }
            }
            if(!isNoGravity()) {
                if(isInWater() || isInLava()) {
                    onInsideBubbleColumn(false);
                    wasFloatingUp = true;
                } else if(wasFloatingUp) {
                    setNoGravity(true);
                    setDeltaMovement(Vec3.ZERO);
                }
            }
        }
        super.tick();
    }

