            if(player.isOnFire()) {
                player.clearFire();
            } else {
                if(biome.value().getBaseTemperature() >= 2.0F) {
                    player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, duration, 0));
                }
            }
        }
