public void addModifiableSlots() {
        if(this.wrapper.tanksVisible()) {
            this.extendedScreenOffset = 22;
        }

        //Update Player Slots, Storage Slots
        this.updateSlotsPosition();

        //Update Upgrade Slots
        this.updateBackpackUpgradeSlots();

