public static void clearSlotsAndPlaySound(Player player, ItemStackHandler handler, int size, boolean forbiddenOnly) {
        boolean playSound = false;
        for(int i = 0; i < size; i++) {
            boolean flag = clearSlot(handler, player, i, forbiddenOnly);
            if(flag) playSound = true;
        }
        if(playSound) {
            playSound(player);
        }
    }

public static boolean clearSlot(ItemStackHandler handler, Player player, int index, boolean forbiddenOnly) {
        boolean flag = forbiddenOnly ? !BackpackSlotItemHandler.isItemValid(handler.getStackInSlot(index)) : !handler.getStackInSlot(index).isEmpty();
        if(flag) {
            if(player == null) return false;
            if(!player.isAlive() || (player instanceof ServerPlayer serverPlayer && serverPlayer.hasDisconnected())) {
                ItemStack stack = handler.getStackInSlot(index).copy();
                handler.setStackInSlot(index, ItemStack.EMPTY);

                player.drop(stack, false);
                return false;
            } else {
                ItemStack stack = handler.getStackInSlot(index);
                handler.setStackInSlot(index, ItemStack.EMPTY);
                player.getInventory().placeItemBackInInventory(stack);
                return true;
            }
        }
        return false;
    }

