    public void playDiscToPlayer(int entityId, @Nullable SoundEvent jukeboxSong, @Nullable Component description) {
        if(jukeboxSong == null) {
            return;
        }

        var level = Minecraft.getInstance().level;
        if(level == null) {
            return;
        }

        var entity = level.getEntity(entityId);
